"""gitignore-style pattern matching. See task.md."""

from __future__ import annotations


class PatternError(ValueError):
    """Raised for a malformed character class or a dangling escape."""


def is_ignored(patterns: list[str], path: str, is_dir: bool) -> bool:
    """Return True when `path` is ignored by `patterns`."""

    compiled_patterns = []

    for line in patterns:
        line = _remove_trailing_spaces(line)

        if not line:
            continue

        if line.startswith('#'):
            continue

        is_negation = False
        if line.startswith('!'):
            is_negation = True
            line = line[1:]

        is_dir_only = False
        if line.endswith('/'):
            is_dir_only = True
            line = line[:-1]

        if not line:
            continue

        _validate_pattern(line)
        compiled_patterns.append((line, is_negation, is_dir_only))

    matched_is_negation = None

    for pattern_text, is_negation, is_dir_only in compiled_patterns:
        if is_dir_only and not is_dir:
            continue

        if _match_path(pattern_text, path):
            matched_is_negation = is_negation

    if matched_is_negation is None:
        return False

    return not matched_is_negation


def _remove_trailing_spaces(line: str) -> str:
    """Remove trailing spaces unless escaped."""
    i = len(line) - 1

    while i >= 0 and line[i] == ' ':
        i -= 1

    if i < 0:
        return ""

    j = i
    while j >= 0 and line[j] == '\\':
        j -= 1

    backslash_count = i - j

    if backslash_count % 2 == 1:
        return line
    else:
        return line[:i + 1]


def _validate_pattern(pattern: str) -> None:
    """Validate a pattern and raise PatternError if malformed."""
    segments = pattern.split('/')
    for segment in segments:
        _validate_segment(segment)


def _validate_segment(segment: str) -> None:
    """Validate a single segment."""
    i = 0
    while i < len(segment):
        if segment[i] == '\\':
            if i + 1 >= len(segment):
                raise PatternError("Dangling backslash")
            i += 2
        elif segment[i] == '[':
            j = i + 1
            if j < len(segment) and segment[j] in ('!', ']'):
                j += 1
            while j < len(segment) and segment[j] != ']':
                if segment[j] == '\\' and j + 1 < len(segment):
                    j += 2
                else:
                    j += 1
            if j >= len(segment):
                raise PatternError("Unclosed character class")

            _validate_char_class(segment[i + 1:j])
            i = j + 1
        else:
            i += 1


def _validate_char_class(class_content: str) -> None:
    """Validate a character class."""
    if class_content and class_content[0] == '!':
        class_content = class_content[1:]

    i = 0
    while i < len(class_content):
        if class_content[i] == '\\' and i + 1 < len(class_content):
            i += 2
        elif i + 2 < len(class_content) and class_content[i + 1] == '-':
            start = ord(class_content[i])
            end = ord(class_content[i + 2])
            if end < start:
                raise PatternError("Invalid character range")
            i += 3
        else:
            i += 1


def _match_path(pattern: str, path: str) -> bool:
    """Match a path against a pattern."""
    if '/' in pattern:
        if pattern.startswith('/'):
            pattern = pattern[1:]
        pattern_segments = pattern.split('/')
        path_segments = path.split('/')
        return _match_segments(pattern_segments, path_segments)
    else:
        path_segments = path.split('/')
        return _match_segment(pattern, path_segments[-1])


def _match_segments(patterns: list[str], path: list[str]) -> bool:
    """Match pattern segments against path segments."""
    return _match_segs_impl(patterns, 0, path, 0)


def _match_segs_impl(patterns: list[str], pi: int, path: list[str], si: int) -> bool:
    """Recursive helper to match patterns[pi:] against path[si:]."""

    if pi == len(patterns):
        return si == len(path)

    if patterns[pi] == '**':
        if pi == len(patterns) - 1:
            return si < len(path)

        for i in range(si, len(path) + 1):
            if _match_segs_impl(patterns, pi + 1, path, i):
                return True
        return False

    if si >= len(path):
        return False

    if _match_segment(patterns[pi], path[si]):
        return _match_segs_impl(patterns, pi + 1, path, si + 1)

    return False


def _match_segment(pattern: str, segment: str) -> bool:
    """Match a single segment against a glob pattern."""
    return _match_seg_impl(pattern, 0, segment, 0)


def _match_seg_impl(pattern: str, pi: int, segment: str, si: int) -> bool:
    """Recursive helper to match pattern[pi:] against segment[si:]."""

    if pi == len(pattern):
        return si == len(segment)

    if pattern[pi] == '\\':
        if pi + 1 >= len(pattern):
            raise PatternError("Dangling backslash")
        if si >= len(segment) or pattern[pi + 1] != segment[si]:
            return False
        return _match_seg_impl(pattern, pi + 2, segment, si + 1)

    if pattern[pi] == '*':
        for i in range(si, len(segment) + 1):
            if _match_seg_impl(pattern, pi + 1, segment, i):
                return True
        return False

    if pattern[pi] == '?':
        if si >= len(segment):
            return False
        return _match_seg_impl(pattern, pi + 1, segment, si + 1)

    if pattern[pi] == '[':
        j = pi + 1
        if j < len(pattern) and pattern[j] in ('!', ']'):
            j += 1
        while j < len(pattern) and pattern[j] != ']':
            if pattern[j] == '\\' and j + 1 < len(pattern):
                j += 2
            else:
                j += 1

        if j >= len(pattern):
            raise PatternError("Unclosed character class")

        class_content = pattern[pi + 1:j]
        negate = False
        if class_content and class_content[0] == '!':
            negate = True
            class_content = class_content[1:]

        if si >= len(segment):
            return False

        char = segment[si]
        matches = _char_in_class(char, class_content)
        if negate:
            matches = not matches

        if matches:
            return _match_seg_impl(pattern, j + 1, segment, si + 1)
        return False

    if si >= len(segment) or pattern[pi] != segment[si]:
        return False
    return _match_seg_impl(pattern, pi + 1, segment, si + 1)


def _char_in_class(char: str, class_content: str) -> bool:
    """Check if char is in the character class."""
    i = 0
    while i < len(class_content):
        if class_content[i] == '\\' and i + 1 < len(class_content):
            if class_content[i + 1] == char:
                return True
            i += 2
        elif i + 2 < len(class_content) and class_content[i + 1] == '-':
            start = ord(class_content[i])
            end = ord(class_content[i + 2])
            if start <= ord(char) <= end:
                return True
            i += 3
        else:
            if class_content[i] == char:
                return True
            i += 1
    return False
